function pluginNotFound() {
  return {
    status: 404,
    headers: { 'Content-Type': 'application/json' },
    body: '{"error":"Not found."}',
  };
}

function pluginOops() {
  return {
    status: 500,
    headers: { 'Content-Type': 'application/json' },
    body: '{"error":"Something went wrong."}',
  };
}

function pluginBlankStatus() {
  return {
    version: PLUGIN_VERSION,
    build: PLUGIN_BUILD,
    paired: false,
    org: null,
    decadentUrl: 'https://decadentcoffee.app',
    state: 'unpaired',
    message: MSG_UNPAIRED,
    lastClaimAt: null,
    lastJob: null,
    lastError: null,
    nextPollInS: null,
  };
}

function createPlugin(host, overrides) {
  const ov = isDict(overrides) ? overrides : {};
  const setTimeoutFn = setTimeout;
  const clearTimeoutFn = clearTimeout;
  const fetchFn = fetch;
  const nowFn = typeof ov.now === 'function' ? ov.now : function pluginNow() { return Date.now(); };
  const cfg = {
    decaidUrl: ov.decaidUrl != null ? ov.decaidUrl : 'http://localhost:8080',
    fetch: fetchFn,
    setTimeout: setTimeoutFn,
    clearTimeout: clearTimeoutFn,
    now: nowFn,
    decaidTimeoutMs: ov.decaidTimeoutMs != null ? ov.decaidTimeoutMs : DECAID_TIMEOUT_MS,
    removeEnabled: ov.removeEnabled != null ? ov.removeEnabled : false,
    sleep: typeof ov.sleep === 'function' ? ov.sleep : function pluginSleep(seconds) {
      return sleep({ setTimeout: setTimeoutFn }, seconds);
    },
  };
  const deps = {
    fetch: fetchFn,
    setTimeout: setTimeoutFn,
    clearTimeout: clearTimeoutFn,
    now: nowFn,
    log(message) {
      try {
        if (host && typeof host.log === 'function') host.log(message);
      } catch (err) {
        // The host logger is best-effort.
      }
    },
  };

  let current = null;

  const plugin = {
    id: PLUGIN_ID,
    version: PLUGIN_VERSION,
    onLoad(settings) {
      try {
        if (current) current.stop();
        current = null;
        const clean = isDict(settings) ? settings : {};
        current = createClient({
          host: host,
          deps: deps,
          settings: clean,
          overrides: {
            version: PLUGIN_VERSION,
            build: PLUGIN_BUILD,
            adapter: cfg,
            storageWaitMs: ov.storageWaitMs,
            decadentTimeoutMs: ov.decadentTimeoutMs,
          },
        });
        current.start();
      } catch (err) {
        // onLoad never throws. Drop a half-started loop so no timer remains.
        try {
          if (current) current.stop();
        } catch (stopErr) {
          // The host is already failing.
        }
      }
    },
    onUnload() {
      try {
        if (current) current.stop();
      } catch (err) {
        // Unload never throws.
      }
    },
    onEvent(event) {
      try {
        if (!event || !current) return;
        if (event.name === 'storageRead') current.onStorageRead(event.payload);
        else if (event.name === 'shotStored' && current.onShotStored) current.onShotStored();
      } catch (err) {
        // Events the plugin does not own are ignored, including a bad payload.
      }
    },
    handleHttpRequest(request) {
      try {
        if (request && request.endpoint === 'status') {
          const body = current ? current.status() : pluginBlankStatus();
          return {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body),
          };
        }
      } catch (err) {
        return {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(pluginBlankStatus()),
        };
      }
      if (current && typeof current.http === 'function') {
        try {
          const out = current.http(request);
          if (out && typeof out.then === 'function') {
            return out.then(
              (value) => value || pluginNotFound(),
              () => pluginOops(),
            );
          }
          if (out) return out;
        } catch (err) {
          return pluginOops();
        }
      }
      return pluginNotFound();
    },
  };

  if (ov.exposeInternals === true) {
    plugin.internals = {
      util: pluginUtil(),
      sha256Hex: sha256Hex,
      shots: pluginShots(),
      decaid: pluginDecaid(),
      client: pluginClient(),
      cfg: cfg,
    };
  }
  return plugin;
}
